import sys
from functools import lru_cache

data = sys.stdin.read().split()
n = int(data[0])
nums = tuple(int(x) for x in data[1:1 + n])

@lru_cache(maxsize=None)
def f(t):
    # try every balloon as the next one to burst
    if not t:
        return 0
    best = 0
    for i in range(len(t)):
        l = t[i - 1] if i > 0 else 1
        r = t[i + 1] if i + 1 < len(t) else 1
        best = max(best, l * t[i] * r + f(t[:i] + t[i + 1:]))
    return best

a = (1,) + nums + (1,)

@lru_cache(maxsize=None)
def g(i, j):
    # best coins for the balloons strictly between positions i and j, choosing the last one to burst
    best = 0
    for k in range(i + 1, j):
        best = max(best, g(i, k) + g(k, j) + a[i] * a[k] * a[j])
    return best

if n <= 9:
    print(f(nums))
else:
    sys.setrecursionlimit(10000)
    print(g(0, n + 1))

