    tests.append(fmt([rng.randint(0, 100) for _ in range(60)]))
    tests.append(fmt([rng.randint(0, 100) for _ in range(200)]))
    tests.append(fmt([100] * 200))
    tests.append(fmt([rng.choice([0, 1, 100]) for _ in range(200)]))
    return tests

